Simplicite.UI.BusinessObjects.DemoClient=class extends Simplicite.UI.BusinessObject{map(){const loadLeafLet=new Promise((resolve,_reject)=>{$ui.loadParts([{name:'leaflet-css',url:`${$root}/scripts/leaflet/leaflet.css`,type:'CSS'},{name:'leaflet-js',url:`${$root}/scripts/leaflet/leaflet.js`,}],resolve);});const loadData=new Promise((resolve,reject)=>{const data={};data.row_id=$ui.getUIField(null,this,'row_id').ui.val();if(data.row_id&&data.row_id!='0'){const coords=$ui.getUIField(null,this,'demoCliCoords').ui.val().replace(';',',').split(',');data.latitude=coords[0];data.longitude=coords[1];data.name=$.escapeHTML($ui.getUIField(null,this,'demoCliFirstname').ui.val()+' '+
$ui.getUIField(null,this,'demoCliLastname').ui.val());data.address=$.escapeHTML($ui.getUIField(null,this,'demoCliAddress1').ui.val()+', '+
$ui.getUIField(null,this,'demoCliZipCode').ui.val()+' '+
$ui.getUIField(null,this,'demoCliCity').ui.val()+', '+
$ui.getUIField(null,this,'demoCliCountry').ui.val());resolve(data);}
else{reject();}});const getSettings=new Promise(res=>$ui.grant.getParameter(s=>res(JSON.parse(s)),'MAP_SETTINGS'));Promise.all([loadData,getSettings,loadLeafLet]).then(([data,mapSettings])=>{$('#client-map').show();const map=L.map('client-map').setView([data.latitude,data.longitude],13);map.attributionControl.setPrefix(false);L.tileLayer(mapSettings.tileLayer,{maxZoom:mapSettings.maxZoom,attribution:mapSettings.attribution}).addTo(map);const marker=L.marker([data.latitude,data.longitude]).addTo(map);marker.bindPopup(`<b>${data.name}</b><br/>${data.address}`);});}};